    "steps": [
      {
        "id": "step-01",
        "instruction": "将20—24只带壳生大虾去壳、去虾线，保留虾头和虾壳。虾肉放回冰箱冷藏备用。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "confirm",
        "safetyNote": ""
      },
      {
        "id": "step-02",
        "instruction": "先制作高汤。在大锅中以中大火加热1汤匙橄榄油，加入粗切的1个洋葱、200克罐装碎番茄、粗切的6瓣大蒜，以及预留的虾头和虾壳，炒3—4分钟。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-03",
        "instruction": "倒入2升清水，加入1块鸡高汤块和1个八角。煮沸后转为慢煮，煮30分钟。",
        "duration": 1800,
        "heat": null,
        "timerRequired": true,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-04",
        "instruction": "让高汤稍微冷却，再分批放入搅拌机或料理机打碎，用细筛过滤。稍后制作海鲜饭时取其中1.5升使用。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-05",
        "instruction": "在大海鲜饭锅或特大煎锅中加热2汤匙橄榄油，放入500克鮟鱇鱼块，每面煎几分钟，直到表面上色，取出备用。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-06",
        "instruction": "在锅中加入切细碎的1个大号洋葱，炒4—5分钟，直到变软。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-07",
        "instruction": "拌入500克海鲜饭米，翻炒30秒，让米粒稍微烘香。",
        "duration": 30,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "stir",
        "safetyNote": ""
      },
      {
        "id": "step-08",
        "instruction": "加入切片的4瓣大蒜、2茶匙烟熏红椒粉、1撮藏红花；如果使用卡宴辣椒粉，也在此时加入1茶匙。继续炒30秒。",
        "duration": 30,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-09",
        "instruction": "拌入另外200克罐装碎番茄和1.5升刚做好的高汤。煮沸后调低火力，保持微沸并搅拌，煮约10分钟，此时米粒应仍带有嚼劲。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "stir",
        "safetyNote": ""
      },
      {
        "id": "step-10",
        "instruction": "将鮟鱇鱼放回锅中，同时加入冷藏备用的虾肉、500克清理干净的贻贝、100克冷冻豌豆和100克冷冻嫩蚕豆。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": ""
      },
      {
        "id": "step-11",
        "instruction": "用大烤盘或锡纸盖住锅，以小火再煮10—15分钟，直到贻贝开口、虾肉熟透。",
        "duration": null,
        "heat": "low",
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "wait",
        "safetyNote": ""
      },
      {
        "id": "step-12",
        "instruction": "上桌前撒上1把粗切欧芹叶。这份配方供8人食用。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "confirm",
        "safetyNote": ""
      }
    ],
    "sourceLimitations": [
      "来源分别为海鲜饭和自制虾高汤列出橄榄油、洋葱、番茄及大蒜，已保留各自用量。高汤加入2升清水，但海鲜饭只取过滤后的高汤1.5升；来源未说明最终高汤产量及其余高汤如何处理，不把2升入锅水等同于2升成品高汤。",
      "鮟鱇鱼仅写每面煎几分钟，主锅加热油时没有明确火力；来源也未给预热、稍微冷却和虾肉冷藏的时长，不补造固定值。洋葱炒4—5分钟及最后加盖煮10—15分钟均保留范围，不设置固定倒计时。",
      "来源要求米饭阶段保持微沸并搅拌，约10分钟时米仍有嚼劲，之后加入海鲜和豆类加盖小火煮。没有规定锅巴或额外关火焖制阶段，不加入这些其他版本的操作。",
      "来源以贻贝开口和虾肉熟透为最后阶段判据，没有给海鲜内部温度及不开口贻贝的处理说明，不补造来源未载条件。基础配方明确含鱼、虾、贻贝和鸡高汤块，设置vegetarian:false；鸡高汤块的具体组成未展开，不保证其不存在其他过敏原。"
    ],
