      "来源煎肉丸仅要求上色，回到肉汁酱后只说加热至热透，没有煎制火力、各批时间、最终加热时间或内部温度。保留原文完成线索，不补造安全温度或默认煨煮分钟数。",
      "牛肉高汤可由高汤块制成，但来源未提供产品具体组成。配方含猪肉与牛肉高汤，为非素食，鸡蛋、黄油、白面包屑和普通面粉涉及蛋、乳制品及小麦。来源没有加入酒类，不沿用另一候选的酱油、苹果醋或其他调料。"
